const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || response.message?.content || response.output || response.text || "";

const prev = $("Prepare Documentation Prompt").item?.json || $("Generate Update Prompt").item?.json || {};

function parseFailure(reason) {
  return [{
    json: {
      ...prev,
      isError: true,
      title: "Documentation Parsing Failed",
      description: reason,
      sections: [{
        type: "text",
        title: "Parsing Error",
        content: "The AI response could not be turned into valid documentation.\n\n" + reason
      }]
    }
  }];
}

if (!raw) {
  return parseFailure("AI response was empty.");
}

let cleaned = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const start = cleaned.indexOf("{");
if (start === -1) {
  return parseFailure("No JSON object found in the AI response.");
}

let depth = 0;
let inString = false;
let escapeNext = false;
let end = -1;

for (let i = start; i < cleaned.length; i++) {
  const char = cleaned[i];
  if (inString) {
    if (escapeNext) {
      escapeNext = false;
    } else if (char === "\\") {
      escapeNext = true;
    } else if (char === '"') {
      inString = false;
    }
  } else {
    if (char === '"') {
      inString = true;
    } else if (char === "{") {
      depth++;
    } else if (char === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
}

if (end === -1) {
  return parseFailure("The AI response's JSON object was incomplete or unbalanced.");
}

cleaned = cleaned.slice(start, end + 1);
cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");
cleaned = cleaned.replace(/"(?:[^"\\]|\\.)*"/g, function (match) {
  return match
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t")
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");
});
cleaned = cleaned.replace(/,\s*([\}\]])/g, "$1");

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return parseFailure(
    "Failed to parse AI JSON: " + err.message + " | Snippet: " + cleaned.substring(0, 100)
  );
}

// --- SURGICAL MERGE LOGIC ---
if (prev && prev.mode === "update" && prev.existingDoc) {
  const oldDoc = prev.existingDoc;

  // Deterministic skip — JavaScript decided, ignore LLM response
  if (prev.preSkip === true) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: oldDoc.sections || []
      }
    }];
  }

  // LLM decided to skip
  if (parsed.skip === true) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: oldDoc.sections || []
      }
    }];
  }

  let mergedSections = [...(oldDoc.sections || [])];
  const patches = parsed.updated_sections || [];

  if (patches.length === 0) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: mergedSections
      }
    }];
  }

  for (const patch of patches) {
    if (!patch.id) continue;
    const index = mergedSections.findIndex((s) => s.id === patch.id);
    if (index !== -1) {
      // Spread existing first so id/type/title are never lost if LLM omits them
      mergedSections[index] = { ...mergedSections[index], ...patch };
    } else {
      // New section — append it
      mergedSections.push(patch);
    }
  }

  return [{
    json: {
      ...prev,
      isError: false,
      title: oldDoc.title || prev.title,
      description: oldDoc.description || prev.description,
      sections: mergedSections
    }
  }];
}

// Create Mode
return [{
  json: {
    ...prev,
    ...parsed,
    isError: false
  }
}];

const filePath = $json.file_path || "";
const repo = $json.repo || "";

// One doc per REPOSITORY now (not per file) -- slug identifies the whole repo doc.
const repoSlug = repo
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "");

// Stable per-file section id, used to target only this file section inside
// the repo-level doc when merging (see "Generate Update Prompt").
const sectionId = "file-" + filePath
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "");

const docPath = `content/docs/${repoSlug}.mdx`;

return [{
  json: {
    ...$json,
    slug: repoSlug,
    section_id: sectionId,
    doc_path: docPath
  }
}];

// The HTTP node has "Full Response" enabled, so the item is always a single
// object { statusCode, headers, body } — never auto-split by n8n, which
// otherwise happens whenever a top-level JSON array is returned.
const response = $("Check Existing Doc In Supabase").item.json;
const rows = response?.body;

// A successful match returns an array of rows; no match returns an empty array.
const exists = Array.isArray(rows) && rows.length > 0;

return [{
  json: {
    ...$("Find Existing Doc").item.json,
    doc_exists: exists
  }
}];

const existing = $input.first().json;
const newCode = $("Fetch GitHub File").first().json.code;
const find = $("Find Existing Doc").first().json;
const filePath = find.file_path;

const existingDoc = {
  ...existing.content,
  title: existing.title,
  description: existing.description
};
const existingSections = (existing.content && existing.content.sections) || [];

// Deterministic skip — never ask the LLM to decide this
const lowerPath = (filePath || '').toLowerCase();
const preSkip =
  lowerPath.includes('.github/') ||
  lowerPath.includes('/workflows/') ||
  lowerPath.endsWith('.yml') ||
  lowerPath.endsWith('.yaml') ||
  lowerPath.endsWith('.json') ||
  lowerPath.endsWith('.lock') ||
  lowerPath.endsWith('.md') ||
  lowerPath.endsWith('.gitignore') ||
  lowerPath.includes('/test') ||
  lowerPath.includes('.test.') ||
  lowerPath.includes('.spec.');

// Build section list WITH their current content so the model can see what
// already exists and surgically decide what (if anything) to change.
const sectionList = existingSections.map(s => {
  let contentSnippet = '';
  if (typeof s.content === 'string') {
    contentSnippet = s.content.substring(0, 800);
  } else if (s.content) {
    contentSnippet = JSON.stringify(s.content).substring(0, 800);
  }
  return '- id: ' + s.id + ', type: ' + s.type + ', title: ' + s.title + '\n  FULL EXISTING CONTENT (preserve this, only append/modify the specific part that changed):\n  ' + contentSnippet;
}).join('\n\n');

const updateJson = '{ "updated_sections": [ { "id": "<exact-existing-id>", "type": "<same-type-as-existing>", "title": "<same-title-as-existing>", "content": "<FULL content: existing content kept intact + only the changed part added or revised>" } ] }';

const prompt =
  'You are maintaining investor-grade product documentation for a software system.\n' +
  'This document describes the ENTIRE product. The file below is ONE component of many in the codebase.\n\n' +
  'Your task: decide if this ONE file change warrants updating any existing doc sections.\n\n' +
  'STRICT RULES — READ CAREFULLY:\n' +
  '1. The document is about the WHOLE product, not this single file. Do NOT rewrite sections to be about just this file.\n' +
  '2. LOCKED SECTIONS — these NEVER change from a single file commit unless the core product value proposition fundamentally changed: executive-summary, business-problem, superior-approach, investor-value-proposition, final-conclusion.\n' +
  '3. MOST commits should return { "skip": true }. Adding a method, fixing a bug, or updating a config file almost never justifies updating investor documentation.\n' +
  '4. Maximum 2 sections may be returned in updated_sections. If you think more than 2 need updating, return { "skip": true } instead — that signals a major refactor requiring human review.\n' +
  '5. Only use section ids exactly as listed below. Do NOT invent new ids.\n' +
  '6. You MUST copy the exact same id, type, and title from the existing section — never change them.\n' +
  '7. SURGICAL EDIT ONLY: your updated content field must contain the COMPLETE existing content verbatim, with only the specific changed part appended or modified inline. Do NOT summarise, shorten, or restructure existing content. If you cannot preserve the full existing content, return { "skip": true } instead.\n' +
  '8. You may add a NEW section (with a new unique id) ONLY if the file introduces a genuinely new capability not covered by any existing section. New sections follow the same investor-grade format.\n\n' +
  'EXISTING DOCUMENT SECTIONS (preserve all content exactly):\n' + sectionList + '\n\n' +
  'CHANGED FILE: ' + filePath + '\n\n' +
  'FILE CODE:\n' + (newCode || '').substring(0, 8000) + '\n\n' +
  'Return ONLY one of these JSON formats (no markdown, no explanation):\n' +
  'Nothing to update: { "skip": true }\n' +
  'Sections to update or add (max 2): ' + updateJson;

return [{
  json: {
    ...find,
    mode: "update",
    preSkip: preSkip,
    metadata: existing.content?.metadata || {},
    architecture: existing.content?.architecture || {},
    existingDoc: existingDoc,
    prompt
  }
}];

const body = $input.first().json.body || {};

const repo = body.repo;
if (!repo) {
  throw new Error("Missing repo");
}

const branch = body.branch || "main";
const changedFiles = Array.isArray(body.changed_files) ? body.changed_files : [];

return changedFiles.map(file => ({
  json: {
    repo,
    branch,
    file_path: file
  }
}));
